@MainActor
final class UIState {
    var title = "Draft"
    func publish() {
        title = "Published"
    }
}

nonisolated func run() async {
    let state = await UIState()
    await state.publish()
    let text = await state.title
    print("State: \(text)")
}

await run()

enum DatabaseMetrics {
    @MainActor static var queries = 0
}

func logQuery() async {
    await MainActor.run {
        DatabaseMetrics.queries += 3
        print("Queries: \(DatabaseMetrics.queries)")
    }
}

await logQuery()

class Report {
    var title = "Weekly Summary"
}

func generateReport() async {
    let report = Report()
    let task = Task {
        report.title = "Final Summary"
        return report.title
    }
    let res = await task.value
    print("Report: \(res)")
}

await generateReport()

func calculateScores() async {
    let t = Task {
        var localSum = 0
        for i in 1...3 {
            localSum += i
        }
        return localSum
    }
    let total = await t.value
    print("Total: \(total)")
}

await calculateScores()

final class UnsafeCache: @unchecked Sendable {
    nonisolated(unsafe) var rawPointerTag: Int = 42
}

func testCache() async {
    let cache = UnsafeCache()
    let t = Task {
        cache.rawPointerTag
    }
    let res = await t.value
    print("Tag: \(res)")
}

await testCache()

