struct UserPreferences: Sendable {
    let soundEnabled: Bool
    let volume: Int
}

func readPrefs() async {
    let prefs = UserPreferences(soundEnabled: true, volume: 80)
    let t = Task.detached {
        "Sound: \(prefs.soundEnabled), Volume: \(prefs.volume)"
    }
    let res = await t.value
    print(res)
}

await readPrefs()

actor MigrationTracker {
    var migratedCount = 0

    func step() {
        migratedCount += 10
    }

    func total() -> Int {
        migratedCount
    }
}

func executeMigration() async {
    let tracker = MigrationTracker()
    await tracker.step()
    let count = await tracker.total()
    print("Migrated: \(count)%")
}

await executeMigration()

