func computeSumAsync(numbers: [Int]) async -> Int {
    let task = Task {
        numbers.reduce(0, +)
    }
    return await task.value
}

func testSum() async {
    let total = await computeSumAsync(numbers: [10, 20, 30])
    print("Sum: \(total)")
}

await testSum()
